  "arguments": [
    {
      "premise": "As the three parts of the soul must be ordered, so must the three classes of the state.",
      "conclusion": "Justice is minding your own business."
    }
  ],
  "defines_key_terms": false,
  "acknowledges_counterarguments": false
}

{
