```csharp
using System;

namespace StockExample
{
    // Delegate for the stock price change event
    public delegate void StockPriceChangedEventHandler(object sender, StockPriceChangedEventArgs e);

    // Event arguments class to hold previous and new prices
    public class StockPriceChangedEventArgs : EventArgs
    {
        public decimal OldPrice { get; }
        public decimal NewPrice { get; }

        public StockPriceChangedEventArgs(decimal oldPrice, decimal newPrice)
        {
            OldPrice = oldPrice;
            NewPrice = newPrice;
        }
    }

    // Stock class that raises an event when price changes
    public class Stock
    {
        private decimal _price;

        public string Symbol { get; }

        public decimal Price
        {
            get => _price;
            set
            {
                if (_price != value)
                {
                    decimal oldPrice = _price;
                    _price = value;
                    OnPriceChanged(oldPrice, _price);
                }
            }
        }

        public event StockPriceChangedEventHandler PriceChanged;

        public Stock(string symbol, decimal initialPrice)
        {
            Symbol = symbol;
            _price = initialPrice;
        }

        protected virtual void OnPriceChanged(decimal oldPrice, decimal newPrice)
        {
            PriceChanged?.Invoke(this, new StockPriceChangedEventArgs(oldPrice, newPrice));
        }
    }

    // StockWatcher class that subscribes to the event
    public class StockWatcher
    {
        public void Subscribe(Stock stock)
        {
            stock.PriceChanged += OnStockPriceChanged;
        }

        public void Unsubscribe(Stock stock)
        {
            stock.PriceChanged -= OnStockPriceChanged;
        }

        private void OnStockPriceChanged(object sender, StockPriceChangedEventArgs e)
        {
            Console.WriteLine($"Stock price changed: {e.OldPrice:C} -> {e.NewPrice:C}");
        }
    }

    // Demo program
    class Program
    {
        static void Main()
        {
            // Create a stock
            var apple = new Stock("AAPL", 150.00m);

            // Create a watcher and subscribe
            var watcher = new StockWatcher();
            watcher.Subscribe(apple);

            // Update the price - this triggers the event
            apple.Price = 155.00m;
            apple.Price = 152.50m;
            apple.Price = 160.00m;
        }
    }
}
```

**How it works:**

1. **Delegate** (`StockPriceChangedEventHandler`) - Defines the signature for the event handler method, accepting the sender and event arguments.

2. **EventArgs class** (`StockPriceChangedEventArgs`) - Custom event arguments that hold the old and new price values, allowing subscribers to see what changed.

3. **Stock class** - Contains a `Price` property with a private backing field. When the price is set to a different value, it calls `OnPriceChanged()` which raises the `PriceChanged` event.

4. **StockWatcher class** - Provides `Subscribe()` and `Unsubscribe()` methods to attach/detach its handler to the Stock's event. When the event fires, it prints both prices.

5. **Event invocation** - Uses `?.Invoke()` to safely raise the event only if handlers are subscribed.

**Output:**
```
Stock price changed: $150.00 -> $155.00
Stock price changed: $155.00 -> $152.50
Stock price changed: $152.50 -> $160.00
```

